def _ver(rel):
    """Короткий хеш файла — подставляется в URL, чтобы браузер брал свежие CSS/JS."""
    try:
        return hashlib.md5((ROOT / rel).read_bytes()).hexdigest()[:8]
    except OSError:
        return "0"


