def breadcrumbs(trail):
    parts = [f'<a href="index.html">Главная</a>']
    for label, href in trail:
        if href:
            parts.append(f'<span>/</span><a href="{href}">{e(label)}</a>')
        else:
            parts.append(f'<span>/</span><b>{e(label)}</b>')
    return f'<nav class="crumbs" aria-label="Хлебные крошки">{" ".join(parts)}</nav>'


