def build_product(p):
    page = next(x for x in PAGES if x["file"] == p["file"])
    schema = [
        {"@context": "https://schema.org", "@type": "Product", "name": p["name"],
         "description": p["seo_desc"], "brand": {"@type": "Brand", "name": "СКБ Контур"},
         "category": p["cat"], "url": BASE + "/" + p["file"],
         "image": f"{BASE}/{ICONS}{p['icon']}-512.svg",
         "offers": {"@type": "Offer", "priceCurrency": "RUB", "availability": "https://schema.org/InStock",
                    "url": BASE + "/" + p["file"], "seller": {"@type": "Organization", "name": FIRM}}},
        {"@context": "https://schema.org", "@type": "BreadcrumbList", "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "Главная", "item": BASE + "/"},
            {"@type": "ListItem", "position": 2, "name": "Продукты", "item": BASE + "/products.html"},
            {"@type": "ListItem", "position": 3, "name": p["name"], "item": BASE + "/" + p["file"]}]},
    ]
    hero = f"""<section class="page-hero">
  <div class="container">
    {breadcrumbs([('Продукты', 'products.html'), (p['name'], None)])}
    <div class="page-hero__grid">
      <div>
        <span class="section-eyebrow" style="color:#FF8A3D">{e(p['cat'])}</span>
        <h1>{e(p['name'])}</h1>
        <p class="page-hero__lead">{e(p['lead'])}</p>
        <div class="btn-row" style="margin-top:1.6rem">
          <a class="btn btn--lg" href="{PHONE_HREF}">{ICON_PHONE}Позвонить</a>
          {btn_buy(p, 'btn--lg', light=True)}
          {btn_consult(p, 'btn--lg', light=True)}
        </div>
      </div>
      <div class="page-hero__icon"><img src="{ICONS}{p['icon']}-512.svg" alt="{e(p['name'])}" width="240" height="240"></div>
    </div>
  </div>
</section>"""
    feats = "".join(feature_card(i, f, i * 60) for i, f in enumerate(p["features"]))
    feat_sec = f"""<section class="section">
  <div class="container">
    {section_head('Возможности', f'Что умеет {e(p["short"])}', 'Функции сервиса, которые клиенты используют каждый день.', center=True, reveal='data-reveal')}
    <div class="grid g-3">{feats}</div>
  </div>
</section>"""
    benefits = [
        ("Официальный партнёр", "Работаем с СКБ Контур с 2014 года: лицензии, актуальные цены и официальная поддержка."),
        ("Быстрый старт", "Подключение и настройка без визита в офис — онлайн, в день обращения."),
        ("Поддержка 24/7", "Помогаем с любыми вопросами по продукту: по телефону, в чате и на почте."),
        ("Работа по всей России", "Консультируем удалённо, подписи и доступы выдаём онлайн и с доставкой."),
    ]
    ben = "".join(
        f"""<div class="card card--accent" data-reveal style="--d:{i*80}ms">
  <span class="card__icon" style="color:#FF8A3D">{ICON_SHIELD}</span>
  <h3>{e(t)}</h3><p>{e(d)}</p>
</div>""" for i, (t, d) in enumerate(benefits))
    ben_sec = f"""<section class="section section--mist">
  <div class="container">
    {section_head('Почему мы', 'Почему клиенты покупают {0} именно у нас'.format(e(p['short'])), '', center=True, reveal='data-reveal')}
    <div class="grid g-4">{ben}</div>
  </div>
</section>"""
    faq = [
        (f"Как купить {p['name']} онлайн?",
         "Нажмите кнопку «Купить Онлайн» на этой странице, оставьте телефон — менеджер перезвонит в течение 15 минут, "
         "выставит счёт и подключит продукт. Оплата возможна онлайн по счёту или картой."),
        (f"Сколько стоит {p['name']}?",
         "Стоимость зависит от тарифа, количества пользователей и срока обслуживания. Назовём точную цену после "
         "короткой бесплатной консультации и предложим оптимальный тариф под ваши задачи."),
        ("Нужно ли приезжать в офис?",
         "Нет. Большинство услуг оформляются полностью онлайн. Если требуется выпуск электронной подписи, мы "
         "организуем удалённую идентификацию или доставку готового носителя."),
        ("Работаете ли вы с другими регионами?",
         "Да, мы помогаем клиентам по всей России: консультируем удалённо, оформляем документы и подключаем сервисы "
         "онлайн. Офисы находятся в Красном Селе и Санкт-Петербурге."),
    ]
    pool = [q for q in P if q["cat"] == p["cat"] and q["file"] != p["file"]]
    pool += [q for q in P if q["file"] != p["file"] and q not in pool]
    related = "".join(product_card(x, i * 60) for i, x in enumerate(pool[:3]))
    rel_sec = f"""<section class="section">
  <div class="container">
    {section_head('С этим смотрят', 'Другие продукты и услуги', '', center=True, reveal='data-reveal')}
    <div class="grid g-3">{related}</div>
  </div>
</section>"""
    body = hero + feat_sec + ben_sec + faq_section(faq, title=f"Вопросы о продукте «{p['short']}»") + rel_sec + cta_section(
        f"Попробуйте {p['short']} прямо сейчас",
        "Бесплатная консультация, быстрый запуск и поддержка на всех этапах работы.")
    return head(page, schema) + header() + "<main>" + body + "</main>" + footer()


# ============================================================ файлы
ROBOTS = f"""# Файл robots.txt — {BRAND}
# Адрес сайта: {BASE}/

User-agent: *
Allow: /

User-agent: Scanfactory
Disallow: /

User-agent: Serpstatbot
Disallow: /

User-agent: SemrushBot
Disallow: /

User-agent: AhrefsBot
Disallow: /

Disallow: /*_openstat
Disallow: /assets/js/
Disallow: /build.py

Host: {BASE}/

Sitemap: {BASE}/sitemap.xml
"""


def build_sitemap():
    prio = {"index.html": "1.0", "products.html": "0.9", "about.html": "0.8",
            "contacts.html": "0.8", "news.html": "0.6", "privacy.html": "0.4"}
    urls = []
    for pg in PAGES:
        if pg["file"] == "404.html":
            continue
        p = prio.get(pg["file"], "0.7")
        loc = BASE + "/" if pg["file"] == "index.html" else f"{BASE}/{pg['file']}"
        urls.append(
            f"  <url>\n    <loc>{loc}</loc>\n"
            f"    <lastmod>{TODAY}</lastmod>\n    <changefreq>weekly</changefreq>\n"
            f"    <priority>{p}</priority>\n  </url>")
    return ("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
            "<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n"
            + "\n".join(urls) + "\n</urlset>\n")


README = f"""# {BRAND} — новый сайт

Переделанный сайт официального партнёра СКБ Контур **{FIRM}**.

*   Старый сайт: {OLD}
*   Новый сайт: {BASE}/
*   Репозиторий: https://github.com/system785/ipdss

## Структура

*   `index.html` — главная: первый блок с каруселью услуг и фото довольных предпринимателей (прокрутка в обе стороны)
*   `products.html` — каталог всех сервисов Контура
*   `about.html` — о компании, `contacts.html` — контакты и офисы
*   `news.html` — новости и акции, `privacy.html` — политика конфиденциальности
*   18 страниц продуктов: `ca.html`, `diadoc.html`, `elba.html`, `sverka-nds.html`, `ofd.html`, `market.html`, ...
*   `robots.txt`, `sitemap.xml` — SEO-файлы со ссылкой на адрес нового сайта
*   `assets/` — стили, скрипты, оригинальный логотип, иконки продуктов и фотографии

## SEO

Заголовки расмечены тегами `h1`/`h2`/`h3`, на каждой странице есть уникальные
`title`, `description`, canonical, Open Graph, микроразметка schema.org
(ProfessionalService, Product, FAQPage, BreadcrumbList), файлы robots и sitemap.

## Сборка

```bash
py -3 build.py
```

Генератор пересобирает все HTML-страницы, robots.txt и sitemap.xml.
"""


def main():
    built = {
        "index.html": build_index(),
        "products.html": build_products(),
        "about.html": build_about(),
        "contacts.html": build_contacts(),
        "news.html": build_news(),
        "privacy.html": build_privacy(),
        "404.html": build_404(),
    }
    for p in P:
        built[p["file"]] = build_product(p)
    def optimize(html: str) -> str:
        # фотографии отдаются в WebP (легче примерно на 79 %), PNG остаётся только для og:image
        for stem in ("p2", "p10", "p15", "p17", "p23", "p28", "p29", "p34", "p38", "p42"):
            html = html.replace(f"assets/img/people/{stem}.png",
                                f"assets/img/people/{stem}.webp")
        return html

    for name, html in built.items():
        (ROOT / name).write_text(optimize(html), encoding="utf-8")
    (ROOT / "robots.txt").write_text(ROBOTS, encoding="utf-8")
    (ROOT / "sitemap.xml").write_text(build_sitemap(), encoding="utf-8")
    (ROOT / "README.md").write_text(README, encoding="utf-8")
    total = sum(len(h.encode("utf-8")) for h in built.values())
    print(f"Готово: {len(built)} страниц, {total/1024:.0f} КБ HTML")


if __name__ == "__main__":
    main()
